/*
We are given degree distributions:
- a[i] = number of vertices with indegree i
- b[i] = number of vertices with outdegree i
for a directed graph on N vertices, allowing self-loops, forbidding multiple edges.

Need to determine existence and construct one graph.

Key idea:
Choose concrete indegree sequence d_in[1..N] from a[], and outdegree sequence d_out[1..N] from b[].
Then construct an N x N 0/1 matrix with row sums d_out and column sums d_in.
Since self-loops are allowed, this is exactly the bipartite degree sequence realization problem
(rows = sources, columns = destinations), with at most one edge per ordered pair.
So we need a simple bipartite graph with prescribed left/right degrees.

We use Gale-Ryser theorem constructively via Havel-Hakimi for bipartite graphs:
Repeatedly take a row with largest remaining degree r and connect it to r columns with largest remaining capacities.
This succeeds iff a realization exists.

Because only the multiset of indegrees/outdegrees matters, we can assign degrees to vertices arbitrarily.
So we simply expand the distributions.

Constraints are not stated, so we use O(N^2 log N) style construction and store adjacency matrix as strings.
This is standard and robust for moderate N.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    vector<long long> a(N + 1), b(N + 1);
    for (int i = 0; i <= N; ++i) cin >> a[i];
    for (int i = 0; i <= N; ++i) cin >> b[i];

    long long sumA = 0, sumB = 0, edgesA = 0, edgesB = 0;
    for (int i = 0; i <= N; ++i) {
        if (a[i] < 0 || b[i] < 0) {
            cout << "NO\n";
            return 0;
        }
        sumA += a[i];
        sumB += b[i];
        edgesA += 1LL * i * a[i];
        edgesB += 1LL * i * b[i];
    }

    if (sumA != N || sumB != N || edgesA != edgesB) {
        cout << "NO\n";
        return 0;
    }

    vector<int> indeg, outdeg;
    indeg.reserve(N);
    outdeg.reserve(N);

    for (int d = 0; d <= N; ++d) {
        for (long long k = 0; k < a[d]; ++k) indeg.push_back(d);
        for (long long k = 0; k < b[d]; ++k) outdeg.push_back(d);
    }

    if ((int)indeg.size() != N || (int)outdeg.size() != N) {
        cout << "NO\n";
        return 0;
    }

    // Adjacency matrix
    vector<string> mat(N, string(N, '0'));

    // Rows sorted by remaining outdegree
    vector<pair<int,int>> rows; // {remaining degree, row index}
    rows.reserve(N);
    for (int i = 0; i < N; ++i) rows.push_back({outdeg[i], i});

    // Remaining column capacities
    vector<int> colRem = indeg;

    // Process rows in nonincreasing order of degree
    sort(rows.begin(), rows.end(), [&](auto &x, auto &y){
        if (x.first != y.first) return x.first > y.first;
        return x.second < y.second;
    });

    for (auto [need, r] : rows) {
        if (need < 0 || need > N) {
            cout << "NO\n";
            return 0;
        }
        // Select 'need' columns with largest remaining capacities
        vector<int> ord(N);
        iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int x, int y){
            if (colRem[x] != colRem[y]) return colRem[x] > colRem[y];
            return x < y;
        });

        if (need > 0 && colRem[ord[need - 1]] <= 0) {
            cout << "NO\n";
            return 0;
        }

        for (int j = 0; j < need; ++j) {
            int c = ord[j];
            if (colRem[c] <= 0) {
                cout << "NO\n";
                return 0;
            }
            mat[r][c] = '1';
            --colRem[c];
        }
    }

    for (int x : colRem) {
        if (x != 0) {
            cout << "NO\n";
            return 0;
        }
    }

    cout << "YES\n";
    long long m = edgesA;
    cout << m << '\n';
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (mat[i][j] == '1') {
                cout << i + 1 << ' ' << j + 1 << '\n';
            }
        }
    }

    return 0;
}

