        for (int i = 0; i < N; i++) {
            for (int j = 0; j < a[i]; j++) {
                inDeg.add(i);
            }
        }

        int V = outDeg.size();
        if (inDeg.size() != V) {
            System.out.println("NO");
            return;
        }

        // Sort vertices by out-degree descending (store index)
        Integer[] indices = new Integer[V];
        for (int i = 0; i < V; i++) indices[i] = i;
        Arrays.sort(indices, Comparator.comparingInt(i -> -outDeg.get(i)));

        // in-degree multiset (sorted)
        PriorityQueue<int[]> inHeap = new PriorityQueue<>((x, y) -> y[0] - x[0]); // max-heap by remaining in-degree
        for (int i = 0; i < V; i++) {
            inHeap.offer(new int[]{inDeg.get(i), i});
        }

        List<int[]> edges = new ArrayList<>();
        boolean possible = true;

        for (int idx : indices) {
            int out = outDeg.get(idx);
            List<int[]> temp = new ArrayList<>();
            for (int i = 0; i < out; i++) {
                if (inHeap.isEmpty()) {
