import java.io.*;
import java.util.*;

/*
Construct a directed graph (loops allowed, no multiple edges) from:
- a_i = number of vertices with indegree i
- b_i = number of vertices with outdegree i

Idea:
1) Recover one indegree sequence and one outdegree sequence by assigning degrees to vertices.
   Since only counts matter, any assignment of those multisets to vertices is fine.
2) Check sums match; otherwise impossible.
3) Realize a 0/1 matrix with prescribed row sums (outdegrees) and column sums (indegrees),
   where diagonal entries are allowed. This is exactly a bipartite graph realization problem.
4) Use max flow:
   source -> left vertex u capacity out[u]
   left u -> right v capacity 1 for all pairs (u,v)
   right v -> sink capacity in[v]
   If max flow equals total edges, the chosen edges form the graph.

Constraints are not stated, so use Dinic with adjacency matrix-like complete bipartite edges.
This is O(N^2 * sqrt(V)) in practice via Dinic-ish blocking flow, acceptable for moderate N.
*/

public class Main {
    // ---------- Fast Scanner ----------
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    // ---------- Dinic ----------
    static class Edge {
        int to, rev, cap;
        Edge(int to, int rev, int cap) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
        }
    }

    static class Dinic {
        int n;
        ArrayList<Edge>[] g;
        int[] level, it;

        @SuppressWarnings("unchecked")
        Dinic(int n) {
            this.n = n;
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
            level = new int[n];
            it = new int[n];
        }

        void addEdge(int fr, int to, int cap) {
            Edge fwd = new Edge(to, g[to].size(), cap);
            Edge rev = new Edge(fr, g[fr].size(), 0);
            g[fr].add(fwd);
            g[to].add(rev);
        }

        boolean bfs(int s, int t) {
            Arrays.fill(level, -1);
            ArrayDeque<Integer> q = new ArrayDeque<>();
            level[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : g[v]) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[v] + 1;
                        q.add(e.to);
                    }
                }
            }
            return level[t] >= 0;
        }

        int dfs(int v, int t, int f) {
            if (v == t) return f;
            for (; it[v] < g[v].size(); it[v]++) {
                Edge e = g[v].get(it[v]);
                if (e.cap > 0 && level[v] + 1 == level[e.to]) {
                    int ret = dfs(e.to, t, Math.min(f, e.cap));
                    if (ret > 0) {
                        e.cap -= ret;
                        g[e.to].get(e.rev).cap += ret;
                        return ret;
                    }
                }
            }
            return 0;
        }

        long maxFlow(int s, int t) {
            long flow = 0;
            final int INF = 1 << 30;
            while (bfs(s, t)) {
                Arrays.fill(it, 0);
                int f;
                while ((f = dfs(s, t, INF)) > 0) {
                    flow += f;
                }
            }
            return flow;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        int[] a = new int[N + 1];
        int[] b = new int[N + 1];

        long countInVertices = 0, countOutVertices = 0;
        long sumIn = 0, sumOut = 0;

        for (int i = 0; i <= N; i++) {
            a[i] = fs.nextInt();
            countInVertices += a[i];
            sumIn += 1L * a[i] * i;
        }
        for (int i = 0; i <= N; i++) {
            b[i] = fs.nextInt();
            countOutVertices += b[i];
            sumOut += 1L * b[i] * i;
        }

        if (countInVertices != N || countOutVertices != N || sumIn != sumOut) {
            System.out.println("NO");
            return;
        }

        int[] indeg = new int[N];
        int[] outdeg = new int[N];

        int idx = 0;
        for (int d = 0; d <= N; d++) {
            for (int k = 0; k < a[d]; k++) indeg[idx++] = d;
        }
        idx = 0;
        for (int d = 0; d <= N; d++) {
            for (int k = 0; k < b[d]; k++) outdeg[idx++] = d;
        }

        for (int i = 0; i < N; i++) {
            if (indeg[i] < 0 || indeg[i] > N || outdeg[i] < 0 || outdeg[i] > N) {
                System.out.println("NO");
                return;
            }
        }

        int S = 0;
        int L = 1;
        int R = 1 + N;
        int T = 1 + N + N;
        Dinic dinic = new Dinic(T + 1);

        for (int i = 0; i < N; i++) {
            dinic.addEdge(S, L + i, outdeg[i]);
        }
        for (int j = 0; j < N; j++) {
            dinic.addEdge(R + j, T, indeg[j]);
        }

        // Keep references to left->right edges for reconstruction
        Edge[][] lr = new Edge[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                int from = L + i;
                int before = dinic.g[from].size();
                dinic.addEdge(from, R + j, 1);
                lr[i][j] = dinic.g[from].get(before);
            }
        }

        long flow = dinic.maxFlow(S, T);
        if (flow != sumIn) {
            System.out.println("NO");
            return;
        }

        StringBuilder sb = new StringBuilder();
        sb.append("YES\n");
        for (int i = 0; i < N; i++) {
            boolean first = true;
            for (int j = 0; j < N; j++) {
                // original cap was 1, if now 0 then flow used => edge exists
                int used = (lr[i][j].cap == 0) ? 1 : 0;
                if (!first) sb.append(' ');
                sb.append(used);
                first = false;
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }
}

