#define MAXN 100005

int main() {
    int n;
    scanf("%d", &n);
    int a[MAXN] = {0}, b[MAXN] = {0};
    int sum_in = 0, sum_out = 0;
    int max_deg = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        a[x]++;
        sum_in += x;
        if (x > max_deg) max_deg = x;
    }
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        b[x]++;
        sum_out += x;
        if (x > max_deg) max_deg = x;
    }
    if (sum_in != sum_out) {
        printf("NO\n");
        return 0;
    }

    // Build list of vertices with their out-degree and in-degree
    int out_deg[MAXN], in_deg[MAXN];
    int out_cnt = 0, in_cnt = 0;
    for (int d = 0; d <= max_deg; d++) {
        for (int i = 0; i < b[d]; i++) {
            out_deg[out_cnt++] = d;
        }
    }
    for (int d = 0; d <= max_deg; d++) {
        for (int i = 0; i < a[d]; i++) {
            in_deg[in_cnt++] = d;
        }
    }

    // out_deg and in_deg arrays now have length n each
    // We'll assign edges greedily:
    // For each vertex u (out), assign its outgoing edges to vertices that still need in-degree.
    int out_rem[MAXN]; // remaining out-degree for each out-vertex
    int in_rem[MAXN];  // remaining in-degree for each in-vertex
    for (int i = 0; i < n; i++) {
        out_rem[i] = out_deg[i];
        in_rem[i] = in_deg[i];
    }

    // We'll store edges as adjacency list
    int adj[MAXN][MAXN]; // max n=100 so okay
    int adj_size[MAXN] = {0};

    int in_ptr = 0;
    for (int u = 0; u < n; u++) {
        while (out_rem[u] > 0) {
            if (in_ptr >= n) {
                printf("NO\n");
                return 0;
            }
            if (in_rem[in_ptr] == 0) {
                in_ptr++;
                continue;
            }
            // add edge u -> in_ptr
            adj[u][adj_size[u]++] = in_ptr;
            out_rem[u]--;
            in_rem[in_ptr]--;
        }
    }

    // Check if all in-degrees satisfied
    for (int i = 0; i < n; i++) {
        if (in_rem[i] != 0) {
            printf("NO\n");
            return 0;
        }
    }

    // Output YES and graph
    printf("YES\n");
    // Count total edges
    int total_edges = sum_in;
    printf("%d\n", total_edges);
    for (int u = 0; u < n; u++) {
        for (int j = 0; j < adj_size[u]; j++) {
            printf("%d %d\n", u+1, adj[u][j]+1);
        }
    }

    return 0;
}

