// Greedy: sort by out-degree desc, assign to top in-degree vertices

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

typedef struct {
    int in, out, id;
} Vertex;

static int cmp_desc_out(const void *a, const void *b) {
    const Vertex *x = (const Vertex *)a;
    const Vertex *y = (const Vertex *)b;
    if (x->out != y->out) return y->out - x->out;
    return x->id - y->id;
}

static int cmp_desc_in(const void *a, const void *b) {
    const Vertex *x = (const Vertex *)a;
    const Vertex *y = (const Vertex *)b;
    if (x->in != y->in) return y->in - x->in;
    return x->id - y->id;
}

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *a = (int *)calloc(N + 1, sizeof(int));
    int *b = (int *)calloc(N + 1, sizeof(int));
    for (int i = 0; i <= N; i++) {
        if (scanf("%d", &a[i]) != 1) return 0;
    }
    for (int i = 0; i <= N; i++) {
        if (scanf("%d", &b[i]) != 1) return 0;
    }

    ll suma = 0, sumb = 0, edges = 0;
    for (int i = 0; i <= N; i++) {
        suma += a[i];
        sumb += b[i];
        edges += (ll)i * a[i];
    }
    ll edges2 = 0;
    for (int i = 0; i <= N; i++) edges2 += (ll)i * b[i];

    if (suma != N || sumb != N || edges != edges2) {
        printf("NO\n");
        return 0;
    }

    Vertex *vin = (Vertex *)malloc(N * sizeof(Vertex));
    Vertex *vout = (Vertex *)malloc(N * sizeof(Vertex));
    int idx = 0;
    for (int d = 0; d <= N; d++) {
        for (int c = 0; c < a[d]; c++) {
            vin[idx].in = d;
            vin[idx].out = 0;
            vin[idx].id = idx + 1;
            idx++;
        }
    }

    idx = 0;
    for (int d = 0; d <= N; d++) {
        for (int c = 0; c < b[d]; c++) {
            vout[idx].out = d;
            vout[idx].in = 0;
            vout[idx].id = idx + 1;
            idx++;
        }
    }

    qsort(vin, N, sizeof(Vertex), cmp_desc_in);
    qsort(vout, N, sizeof(Vertex), cmp_desc_out);

    int *inDeg = (int *)calloc(N + 1, sizeof(int));
    int *outDeg = (int *)calloc(N + 1, sizeof(int));

    for (int i = 0; i < N; i++) inDeg[vin[i].id] = vin[i].in;
    for (int i = 0; i < N; i++) outDeg[vout[i].id] = vout[i].out;

    unsigned char *adj = (unsigned char *)calloc((size_t)(N + 1) * (N + 1), sizeof(unsigned char));
    int *from = (int *)malloc((size_t)edges * sizeof(int));
    int *to = (int *)malloc((size_t)edges * sizeof(int));
    ll m = 0;

    int *remIn = (int *)malloc((N + 1) * sizeof(int));
    int *order = (int *)malloc((N + 1) * sizeof(int));

    for (int i = 1; i <= N; i++) remIn[i] = inDeg[i];

    for (int step = 0; step < N; step++) {
        int u = vout[step].id;
        int need = outDeg[u];

        for (int i = 1; i <= N; i++) order[i - 1] = i;

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                int x = order[i], y = order[j];
                if (remIn[x] < remIn[y] || (remIn[x] == remIn[y] && x > y)) {
                    int tmp = order[i];
                    order[i] = order[j];
                    order[j] = tmp;
                }
            }
        }

        int chosen = 0;
        for (int i = 0; i < N && chosen < need; i++) {
            int v = order[i];
            if (adj[(size_t)u * (N + 1) + v]) continue;
            if (remIn[v] <= 0) continue;
            adj[(size_t)u * (N + 1) + v] = 1;
            remIn[v]--;
            from[m] = u;
            to[m] = v;
            m++;
            chosen++;
        }

        if (chosen < need) {
            printf("NO\n");
            return 0;
        }
    }

    for (int i = 1; i <= N; i++) {
        if (remIn[i] != 0) {
            printf("NO\n");
            return 0;
        }
    }

    printf("YES\n");
    printf("%lld\n", m);
    for (ll i = 0; i < m; i++) {
        printf("%d %d\n", from[i], to[i]);
    }

    return 0;
}
